/// <summary>Fetches <c>/subscriptionlines</c> and maps it to <see cref="SubscriptionLine"/>.</summary>
internal sealed class SubscriptionLineSource(Raw.SubscriptionLinesClient client)
    : IEconomicOpenSource<SubscriptionLine>
{
    public bool CanCursor => true;

    public bool CanPage => true;

    public async Task<EconomicCursorPage<SubscriptionLine>> GetCursorPageAsync(
        string? cursor, string? filter, CancellationToken cancellationToken)
    {
        var response = await OpenTransport.SendAsync(
            () => client.GetAllSubscriptionLinesAsync(cursor: cursor, filter: filter, cancellationToken: cancellationToken),
            "GET /subscriptionlines").ConfigureAwait(false);

        var items = new List<SubscriptionLine>(response.Items?.Count ?? 0);
        foreach (var item in response.Items ?? [])
        {
            items.Add(Map(item));
        }

        return new EconomicCursorPage<SubscriptionLine>(items, response.Cursor);
    }

    public async Task<IReadOnlyList<SubscriptionLine>> GetPageAsync(
        string? filter, string? sort, int pageSize, int skipPages, CancellationToken cancellationToken)
    {
        var response = await OpenTransport.SendAsync(
            () => client.GetPageOfSubscriptionLinesAsync(filter: filter, sort: sort, pageSize: pageSize, skipPages: skipPages, cancellationToken: cancellationToken),
            "GET /subscriptionlines/paged").ConfigureAwait(false);

        var items = new List<SubscriptionLine>(response?.Count ?? 0);
        foreach (var item in response ?? Array.Empty<Raw.SubscriptionLine>())
        {
            items.Add(Map(item));
        }

        return items;
    }

    public Task<int> CountAsync(string? filter, CancellationToken cancellationToken) =>
        OpenTransport.SendAsync(
            () => client.GetNumberOfSubscriptionLinesAsync(filter: filter, cancellationToken: cancellationToken),
            "GET /subscriptionlines/count");

    internal static SubscriptionLine Map(Raw.SubscriptionLine source) => new()
    {
        Number = source.Number,
        SubscriptionNumber = source.SubscriptionNumber,
        ProductNumber = source.ProductNumber,
        Description = source.Description,
        Quantity = source.Quantity,
        SpecialPrice = source.SpecialPrice,
        DepartmentNumber = source.DepartmentNumber,
        ObjectVersion = source.ObjectVersion,
    };

    internal static Raw.SubscriptionLine ToGenerated(SubscriptionLine source) => new()
    {
        Number = source.Number,
        SubscriptionNumber = source.SubscriptionNumber,
        ProductNumber = source.ProductNumber,
        Description = source.Description,
        Quantity = source.Quantity,
        SpecialPrice = source.SpecialPrice,
        DepartmentNumber = source.DepartmentNumber,
        ObjectVersion = source.ObjectVersion,
    };
}

